###################################################################################################
#   MSG BUILDER
###################################################################################################

def AP_PDU(choice, procedureCode, criticality, value, elements):
    out = str_AP_PDU % (choice, procedureCode, criticality, value, elements)
    return out


def Transmission_Bandwidth(bw):
    out = ""
    if bw == 5:
        out = "bw25"
    elif bw == 10:
        out = "bw50"
    elif bw == 15:
        out = "bw75"
    elif bw == 20:
        out = "bw100"
    return out


def PLMN_Identity_h(mcc, mnc):
    if len(mnc) == 3:
        plmn = mcc[1] + mcc[0] + mnc[0] + mcc[2] + mnc[2] + mnc[1]
    elif len(mnc) == 2:
        plmn = mcc[1] + mcc[0] + "F" + mcc[2] + mnc[1] + mnc[0]
    else:
        plmn = mcc[1] + mcc[0] + "F" + mcc[2] + mnc[0] + "0"
    return plmn


def ENB_Id_b(enb_id):
    return "{0:020b}".format(enb_id)


def GNB_Id_b(enb_id):
    return "{0:032b}".format(enb_id)


def gNB_ID_b(gnb_id):
    return "{0:022b}".format(gnb_id)


def Ip_to_b(ip_addr):
    ip_int = 0
    for i, val in enumerate(reversed(ip_addr.split("."))):
        ip_int += int(val) << (i * 8)
    return "{0:032b}".format(ip_int)


def TAC_h(tac):
    return "{0:04X}".format(tac)


def X06(value):
    return "{0:06X}".format(value)


def X04(value):
    return "{0:04X}".format(value)


def X02(value):
    return "{0:02X}".format(value)


def b03(value):
    return "{0:03b}".format(value)


def b06(value):
    return "{0:06b}".format(value)


def b08(value):
    return "{0:08b}".format(value)


def b10(value):
    return "{0:010b}".format(value)


def GlobalCell_ID_b(enb_id, cell_id):
    return "{0:028b}".format((enb_id << 8) + cell_id)


def nRcellIdentifier_b(gnb_id, cell_id):
    return "{0:036b}".format((gnb_id << 14) + cell_id)


def GlobalENB_ID(mcc, mnc, enb_id):
    plmn_h = PLMN_Identity_h(mcc, mnc)
    enb_id_b = ENB_Id_b(enb_id)
    out = str_GlobalENB_ID % (plmn_h, enb_id_b)
    return out


def GlobalGNB_ID(mcc, mnc, gnb_id):
    plmn_h = PLMN_Identity_h(mcc, mnc)
    gnb_id_b = gNB_ID_b(gnb_id)
    out = str_GlobalGNB_ID % (plmn_h, gnb_id_b)
    return out


def InitiatingNodeType_EndcX2Setup(enb_config):
    globalENB_ID = GlobalENB_ID(
        enb_config["MCC"], enb_config["MNC"], enb_config["ENB_ID"]
    )
    servedEUTRAcells = ServedEUTRAcellsENDCX2ManagementList(enb_config)
    out = str_InitiatingNodeType_EndcX2Setup % (globalENB_ID + ",\n" + servedEUTRAcells)
    return out


def RespondingNodeType_EndcX2Setup(enb_config):
    globalGNB_ID = GlobalGNB_ID(
        enb_config["MCC"], enb_config["MNC"], enb_config["ENB_ID"]
    )
    servedNRcells = ServedNRcellsENDCX2ManagementList(enb_config)
    out = str_RespondingNodeType_EndcX2Setup % (globalGNB_ID + ",\n" + servedNRcells)
    return out


def RespondingNodeType_EndcConfigUpdate(_enb_config):
  out = str_RespondingNodeType_EndcConfigUpdate
  return out


def ECGI(mcc, mnc, enb_id, cell_id):
    plmn_h = PLMN_Identity_h(mcc, mnc)
    global_cell_id_b = GlobalCell_ID_b(enb_id, cell_id)
    out = str_ECGI % (plmn_h, global_cell_id_b)
    return out


