def BroadcastPLMNs(enb_config):
    broadcast_plmns = enb_config.get("BROADCAST_PLMNS")
    if broadcast_plmns:
        size = len(broadcast_plmns)
        if size > 6:
            raise Exception("Maximum broadcastPLMNs size is 6")
        str_ret = ""
        for i, plmn in enumerate(broadcast_plmns):
            plmn_h = PLMN_Identity_h(plmn["MCC"], plmn["MNC"])
            str_ret += f"                '{plmn_h}'H"
            if i != size - 1:
                str_ret += ",\n"
    else:
        plmn_h = PLMN_Identity_h(enb_config["MCC"], enb_config["MNC"])
        str_ret = f"                '{plmn_h}'H"
    return str_ret

