def ServedCellsDU(vdu_config):
    gnb_id = vdu_config["GNB_ID"]
    bandwidth_scs = vdu_config.get("BANDWIDTH_SCS", None)
    bandwidth_nrb = vdu_config.get("BANDWIDTH_NRB", None)
    freq_band = vdu_config.get("FREQUENCY_BAND", None)
    arfcn = vdu_config.get("ARFCN", None)
    plmn_h = PLMN_Identity_h(vdu_config["MCC"], vdu_config["MNC"])
    tac_h_06 = X06(vdu_config["TAC"])
    tac_h_04 = X04(vdu_config["EPS_TAC"]) if vdu_config["EPS_TAC"] else None
    sst_h = X02(vdu_config["SST"])
    sd_h = X06(vdu_config["SD"])
    cell_dep_type = vdu_config.get("CELL_DEP_TYPE", "")
    elements = ""

    if arfcn and freq_band and bandwidth_nrb and bandwidth_scs:
        mode = "TDD"
    else:
        mode = "FDD"
        ul_bandwidth_scs = vdu_config["UL_BANDWIDTH_SCS"]
        ul_bandwidth_nrb = vdu_config["UL_BANDWIDTH_NRB"]
        ul_freq_band = vdu_config["UL_FREQUENCY_BAND"]
        ul_arfcn = vdu_config["UL_ARFCN"]
        dl_bandwidth_scs = vdu_config["DL_BANDWIDTH_SCS"]
        dl_bandwidth_nrb = vdu_config["DL_BANDWIDTH_NRB"]
        dl_freq_band = vdu_config["DL_FREQUENCY_BAND"]
        dl_arfcn = vdu_config["DL_ARFCN"]

    for i, cell in enumerate(vdu_config["SERVED_CELLS"]):
        cell_id = cell["CELL_ID"]
        pci = cell["PCI"]
        nr_cell_id_b = nRcellIdentifier_b(gnb_id, cell_id)

        if cell_dep_type == "NSA" and mode == "TDD":
          servedCellsDUItem = str_ServedCellsDUItemTDD_NSA % (
              plmn_h,
              nr_cell_id_b,
              pci,
              tac_h_04,
              plmn_h,
              arfcn,
              freq_band,
              bandwidth_scs,
              bandwidth_nrb,
          )
        elif cell_dep_type == "NSA" and mode =="FDD":
          servedCellsDUItem = str_ServedCellsDUItemFDD_NSA % (
              plmn_h,
              nr_cell_id_b,
              pci,
              tac_h_04,
              plmn_h,
              ul_arfcn,
              ul_freq_band,
              dl_arfcn,
              dl_freq_band,
              ul_bandwidth_scs,
              ul_bandwidth_nrb,
              dl_bandwidth_scs,
              dl_bandwidth_nrb,
          )
        else:
          if mode == "TDD":
              servedCellsDUItem = str_ServedCellsDUItemTDD % (
                  plmn_h,
                  nr_cell_id_b,
                  pci,
                  tac_h_06,
                  tac_h_04,
                  plmn_h,
                  sst_h,
                  sd_h,
                  arfcn,
                  freq_band,
                  bandwidth_scs,
                  bandwidth_nrb,
              ) if tac_h_04 else str_ServedCellsDUItemTDD_no_EPS_TAC % (
                  plmn_h,
                  nr_cell_id_b,
                  pci,
                  tac_h_06,
                  plmn_h,
                  sst_h,
                  sd_h,
                  arfcn,
                  freq_band,
                  bandwidth_scs,
                  bandwidth_nrb,
              )
          else:
              servedCellsDUItem = str_ServedCellsDUItemFDD % (
                  plmn_h,
                  nr_cell_id_b,
                  pci,
                  tac_h_06,
                  tac_h_04,
                  plmn_h,
                  sst_h,
                  sd_h,
                  ul_arfcn,
                  ul_freq_band,
                  dl_arfcn,
                  dl_freq_band,
                  ul_bandwidth_scs,
                  ul_bandwidth_nrb,
                  dl_bandwidth_scs,
                  dl_bandwidth_nrb,
              ) if tac_h_04 else str_ServedCellsDUItemFDD_no_EPS_TAC % (
                  plmn_h,
                  nr_cell_id_b,
                  pci,
                  tac_h_06,
                  plmn_h,
                  sst_h,
                  sd_h,
                  ul_arfcn,
                  ul_freq_band,
                  dl_arfcn,
                  dl_freq_band,
                  ul_bandwidth_scs,
                  ul_bandwidth_nrb,
                  dl_bandwidth_scs,
                  dl_bandwidth_nrb,
              )
        elements += servedCellsDUItem
        if i != len(vdu_config["SERVED_CELLS"]) - 1:
            elements += ",\n"
    out = str_ServedCellsDU % elements
    return out


