def ServedCellsToModify(old_enb_config, new_enb_config):
    new_enb_id = new_enb_config["ENB_ID"]
    new_dl_bandwidth = new_ul_bandwidth = Transmission_Bandwidth(
        new_enb_config["DL_BANDWIDTH"]
    )
    new_ul_earfcn = 18000 + new_enb_config["DL_EARFCN"]
    new_dl_earfcn = new_enb_config["DL_EARFCN"]
    new_plmn_h = PLMN_Identity_h(new_enb_config["MCC"], new_enb_config["MNC"])
    new_broadcast_plmns = BroadcastPLMNs(new_enb_config)
    new_tac_h = TAC_h(new_enb_config["TAC"])
    elements = ""

    for i, cell in enumerate(new_enb_config["SERVED_CELLS"]):
        cell_id = cell["CELL_ID"]
        new_pci = cell["PCI"]
        new_global_cell_id_b = GlobalCell_ID_b(new_enb_id, cell_id)
        old_ecgi = Old_ecgi(
            old_enb_config["MCC"],
            old_enb_config["MNC"],
            old_enb_config["ENB_ID"],
            cell_id,
        )
        servedCellInfo = str_servedCellInfo % (
            new_pci,
            new_plmn_h,
            new_global_cell_id_b,
            new_tac_h,
            new_broadcast_plmns,
            new_ul_earfcn,
            new_dl_earfcn,
            new_ul_bandwidth,
            new_dl_bandwidth,
        )
        elements += "          {\n" + old_ecgi + ",\n" + servedCellInfo
        if "NEIGHBOUR_INFO" in cell:
            elements += ",\n"
            elements += Neighbour_Information(cell["NEIGHBOUR_INFO"])

        elements += "          }"
        if i != len(new_enb_config["SERVED_CELLS"]) - 1:
            elements += ",\n"
        else:
            elements += "\n"
    out = str_ServedCellsToModify % elements
    return out


