###################################################################################################

def S1SetupRequest(enb_config):
    # INITIATING MESSAGE      S1SetupRequest
    # SUCCESSFUL OUTCOME      S1SetupResponse
    # UNSUCCESSFUL OUTCOME    S1SetupFailure
    # PROCEDURE CODE          id-s1Setup
    # CRITICALITY             reject
    choice = "initiatingMessage"
    procedureCode = 17
    criticality = "reject"
    value = "S1SetupRequest"

    elements = GlobalENB_ID(enb_config["MCC"], enb_config["MNC"], enb_config["ENB_ID"])
    elements += ",\n" + ENBname("NECeNB")
    elements += ",\n" + SupportedTAs(
        enb_config["TAC"], enb_config["MCC"], enb_config["MNC"]
    )
    elements += ",\n" + PagingDRX("v128")
    out = AP_PDU(choice, procedureCode, criticality, value, elements)
    return out


def S1SetupResponse(mme_config):
    choice = "successfulOutcome"
    procedureCode = 17
    criticality = "reject"
    value = "S1SetupResponse"

    elements = MMEname("TERM4G-MME")
    elements += ",\n" + ServedGUMMEIs(mme_config)
    elements += ",\n" + RelativeMMECapacity(1)
    out = AP_PDU(choice, procedureCode, criticality, value, elements)
    return out


def MMEConfigurationTransfer(target_enb_config, source_enb_config, ip_addr):
    choice = "initiatingMessage"
    procedureCode = 41
    criticality = "ignore"
    value = "MMEConfigurationTransfer"

    elements = SONConfigurationTransfer(target_enb_config, source_enb_config, ip_addr)
    out = AP_PDU(choice, procedureCode, criticality, value, elements)
    return out


