def X2SetupRequest(enb_config):
    # INITIATING MESSAGE      X2SetupRequest
    # SUCCESSFUL OUTCOME      X2SetupResponse
    # UNSUCCESSFUL OUTCOME    X2SetupFailure
    # PROCEDURE CODE          id-x2Setup
    # CRITICALITY             reject
    choice = "initiatingMessage"
    procedureCode = 6
    criticality = "reject"
    value = "X2SetupRequest"

    globalENB_ID = GlobalENB_ID(
        enb_config["MCC"], enb_config["MNC"], enb_config["ENB_ID"]
    )
    servedCells = ServedCells(enb_config)

    elements = globalENB_ID + ",\n" + servedCells
    if "GU_GROUP_ID_LIST" in enb_config.keys():
        elements += ",\n" + GUGroupIDList(enb_config["GU_GROUP_ID_LIST"])
